<?php/** * 计划任务 */namespace console\controllers;use backend\models\ServiceOrder;use backend\models\Worker;use common\components\SzApi;use Yii;use yii\console\Controller;use yii\web\Response;class ConsoleController extends Controller{    //定时查询派单信息    public function actionIndex(){        $orders = ServiceOrder::find()->where(['status'=>2,'is_pd'=>0])->all();        foreach ($orders as $k=>$v){            if($v->sz_order_number){                $data=[                    'order_number'=>$v->sz_order_number,                    'business_scene_type'=>7                ];                Yii::$app->response->format = Response::FORMAT_JSON;                try {                    $apiService = new SzApi();                    // 原始订单数据                    $orderData = $data;                    $result = $apiService->sendSecureRequest(                        'third_party_platform/orders/business_info',                        $orderData,                        Yii::$app->params['platform_code'], // 平台编码                        Yii::$app->params['public_key'] // RSA公钥                    );                    if ($result['http_code'] === 200) {                        if($result['response']['error_code']==1){                            $order_data=$result['response']['data'];                            if($order_data['order_distribute_info']){                                $v->is_pd=1;                                $v->worker_name=$order_data['order_distribute_info']['contact_name'];                                $v->worker_phone=$order_data['order_distribute_info']['contact_phone'];                                if($v->worker_phone){                                    $old=Worker::find()->where(['worker_phone'=>$v->worker_phone])->limit(1)->one();                                    if(!$old){                                        $new=new Worker();                                        $new->worker_phone=$v->worker_phone;                                        $new->worker_name=$v->worker_name;                                        if($new->save()){                                            $v->worker_id=$new->id;                                        }                                    }                                }                                if($v->save()){                                    echo $v->order_number.'派单成功';                                }                            }                        }                    }                } catch (\Exception $e) {                    echo '系统错误: ' . $e->getMessage();                }            }        }        echo '<br/>'.date('Y-m-d H:i:s');    }}